"""Utilities for parsing clip timestamps generated by an analysis stage."""

from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path

_TIMESTAMP_PATTERN = re.compile(
    r"^\s*"
    r"\[\s*"
    r"([0-9]+:[0-9]{2}(?::[0-9]{2})?)"
    r"\s*[-–—]\s*"
    r"([0-9]+:[0-9]{2}(?::[0-9]{2})?)"
    r"\s*\]"
    r"\s*[-–—]\s*"
    r"(.+?)"
    r"\s*$"
)


@dataclass(frozen=True, slots=True)
class Clip:
    """A section selected from the original video."""

    start_seconds: int
    end_seconds: int
    title: str

    @property
    def duration_seconds(self) -> int:
        return self.end_seconds - self.start_seconds


def time_to_seconds(timestamp: str) -> int:
    """Convert MM:SS or HH:MM:SS into seconds."""

    parts = timestamp.strip().split(":")

    try:
        values = [int(part) for part in parts]
    except ValueError as exc:
        raise ValueError(f"Invalid timestamp '{timestamp}'.") from exc

    if len(values) == 2:
        minutes, seconds = values
        if minutes < 0 or not 0 <= seconds < 60:
            raise ValueError(f"Timestamp outside the valid range: '{timestamp}'.")
        return minutes * 60 + seconds

    if len(values) == 3:
        hours, minutes, seconds = values
        if hours < 0 or not 0 <= minutes < 60 or not 0 <= seconds < 60:
            raise ValueError(f"Timestamp outside the valid range: '{timestamp}'.")
        return hours * 3600 + minutes * 60 + seconds

    raise ValueError(f"Invalid timestamp '{timestamp}'. Use MM:SS or HH:MM:SS.")


def seconds_to_timestamp(total_seconds: int) -> str:
    """Convert seconds into an FFmpeg-compatible HH:MM:SS timestamp."""

    if total_seconds < 0:
        raise ValueError("Seconds cannot be negative.")

    hours, remainder = divmod(total_seconds, 3600)
    minutes, seconds = divmod(remainder, 60)
    return f"{hours:02d}:{minutes:02d}:{seconds:02d}"


def parse_cuts(text: str) -> list[Clip]:
    """Parse one clip per non-empty, non-comment line."""

    clips: list[Clip] = []

    for line_number, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        match = _TIMESTAMP_PATTERN.match(line)
        if match is None:
            raise ValueError(
                f"Invalid clip definition on line {line_number}: '{stripped}'."
            )

        start_seconds = time_to_seconds(match.group(1))
        end_seconds = time_to_seconds(match.group(2))
        title = match.group(3).strip()

        if end_seconds <= start_seconds:
            raise ValueError(
                f"Clip end must be greater than its start on line {line_number}."
            )

        clips.append(Clip(start_seconds, end_seconds, title))

    if not clips:
        raise ValueError("No valid clip definitions were found.")

    return clips


def load_cuts(file_path: str | Path) -> list[Clip]:
    """Read and parse clip definitions from a UTF-8 text file."""

    path = Path(file_path)
    if not path.is_file():
        raise FileNotFoundError(f"Clip file not found: {path}")
    return parse_cuts(path.read_text(encoding="utf-8-sig"))
